import { useState, useRef } from "react";
import ChatSayfasi from "../../components/ChatSayfasi";
import { useApp } from "../../context/AppContext";
import { EmptyState, Pill } from "../../components/UI";

export function IlanVerSayfasi() {
  const { ilanEkle } = useApp();
  const [form, setForm] = useState({
    nereden: "", nereye: "", yuk: "",
    tonaj: "20",
    ucret: "",
    ucretTipi: "duz",
    tarih: "",
    aracTip: "",
    aciklama: "", odemeTuru: "pesin", odemeGun: 0
  });
  const [tamam, setTamam] = useState(false);
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const gonder = () => {
    if (!form.nereden || !form.nereye || !form.yuk || !form.ucret) {
      alert("Lütfen zorunlu alanları doldurun!");
      return;
    }
    const ucret = Number(form.ucret);
    const kdvOrani = form.ucretTipi === "kdv" ? 0.2 : 0;
    const kdvTutari = form.ucretTipi === "kdv" ? ucret * 0.2 : 0;
    const toplamUcret = ucret + kdvTutari;

    ilanEkle({
      ...form,
      ton: form.tonaj === "serbest" ? 0 : Number(form.tonaj),
      ucret: ucret,
      ucretTipi: form.ucretTipi,
      kdvTutari: kdvTutari,
      toplamUcret: toplamUcret,
      odemeTuru: form.odemeTuru,
      odemeGun: Number(form.odemeGun)
    });
    setTamam(true);
    setTimeout(() => {
      setTamam(false);
      setForm({
        nereden: "", nereye: "", yuk: "",
        tonaj: "20",
        ucret: "", ucretTipi: "duz",
        tarih: "",
        aracTip: "", aciklama: "", odemeTuru: "pesin", odemeGun: 0
      });
    }, 2000);
  };

  const inputStyle = "input";
  const Label = ({ children, zorunlu }) => (
    <label className="label">{children} {zorunlu && <span style={{ color: "var(--turuncu)" }}>*</span>}</label>
  );

  if (tamam) return (
    <div className="scroll-content" style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: 400 }}>
      <div style={{ textAlign: "center" }}>
        <div style={{ fontSize: 52, marginBottom: 16 }}>✅</div>
        <div className="display" style={{ fontSize: 28, color: "var(--yesil)" }}>İLAN YAYINDA!</div>
        <div style={{ color: "var(--text3)", marginTop: 8 }}>Teklifler gelmeye başlayacak</div>
        <button onClick={() => setTamam(false)} className="btn btn-secondary btn-full" style={{ marginTop: 20, padding: "12px" }}>
          Devam Et
        </button>
      </div>
    </div>
  );

  return (
    <div className="scroll-content">
      <div className="section-title">YENİ İLAN VER</div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 14 }}>🗺️ Güzergah</div>
        <div className="input-row">
          <div className="input-group">
            <Label zorunlu>Nereden</Label>
            <input className={inputStyle} placeholder="Antalya" value={form.nereden} onChange={e => set("nereden", e.target.value)} />
          </div>
          <div className="input-group">
            <Label zorunlu>Nereye</Label>
            <input className={inputStyle} placeholder="İzmir" value={form.nereye} onChange={e => set("nereye", e.target.value)} />
          </div>
        </div>
      </div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 14 }}>📦 Yük Bilgisi</div>
        <div className="input-group">
          <Label zorunlu>Yük Türü</Label>
          <input className={inputStyle} placeholder="Kömür, çelik, gıda..." value={form.yuk} onChange={e => set("yuk", e.target.value)} />
        </div>
        <div className="input-row">
          <div className="input-group">
            <Label>Tonaj</Label>
            <select className={inputStyle} value={form.tonaj} onChange={e => set("tonaj", e.target.value)} style={{ cursor: "pointer" }}>
              <option value="1">1 Ton</option>
              <option value="5">5 Ton</option>
              <option value="10">10 Ton</option>
              <option value="15">15 Ton</option>
              <option value="20">20 Ton</option>
              <option value="25">25 Ton</option>
              <option value="30">30 Ton</option>
              <option value="40">40 Ton</option>
              <option value="50">50 Ton</option>
              <option value="serbest">Serbest</option>
            </select>
            <div style={{ fontSize: 11, color: "var(--text3)", marginTop: 4 }}>
              Tonaj: {form.tonaj === "serbest" ? "Serbest (Belirtilmedi)" : `${form.tonaj} Ton`}
            </div>
          </div>
          <div className="input-group">
            <Label zorunlu>Ücret (₺)</Label>
            <input className={inputStyle} type="number" placeholder="8500" value={form.ucret} onChange={e => set("ucret", e.target.value)} />
          </div>
        </div>
        <div className="input-group">
          <Label>Araç Tipi</Label>
          <select className={inputStyle} value={form.aracTip} onChange={e => set("aracTip", e.target.value)} style={{ cursor: "pointer" }}>
            <option value="">Seçin...</option>
            {["TIR / Kapalı Kasa", "Frigorifik TIR", "Flatbed / Lowbed", "Tenteli TIR", "Damperli TIR", "Tanker", "Konteyner"].map(t => <option key={t}>{t}</option>)}
          </select>
        </div>
      </div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 14 }}>💰 Fiyat Tipi</div>
        <select className={inputStyle} value={form.ucretTipi} onChange={e => set("ucretTipi", e.target.value)} style={{ cursor: "pointer" }}>
          <option value="duz">Düz Fiyat</option>
          <option value="kdv">+ KDV</option>
        </select>
      </div>

      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 14 }}>📅 Tarih & Notlar</div>
        <div className="input-group">
          <Label>Yükleme Tarihi</Label>
          <input className={inputStyle} type="date" value={form.tarih} onChange={e => set("tarih", e.target.value)} />
        </div>
        <div className="input-group">
          <Label>Açıklama</Label>
          <textarea className={inputStyle} rows={3} placeholder="Özel şartlar, araç özellikleri..." value={form.aciklama} onChange={e => set("aciklama", e.target.value)} style={{ resize: "vertical", lineHeight: 1.6 }} />
        </div>
      </div>

      {/* Ödeme Planı Seçimi */}
      <div className="card" style={{ marginBottom: 12 }}>
        <div className="label" style={{ marginBottom: 12 }}>💰 Ödeme Planı Seçin</div>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr", gap: 8 }}>
          {[
            { tur: "pesin", gun: 0, label: "Peşin", desc: "Hemen tam ödeme", color: "var(--yesil)" },
            { tur: "7-gun", gun: 7, label: "7 Gün", desc: "Teslimden 7 gün sonra", color: "var(--kirmizi)" },
            { tur: "15-gun", gun: 15, label: "15 Gün", desc: "Teslimden 15 gün sonra", color: "var(--sari)" },
            { tur: "30-gun", gun: 30, label: "30 Gün", desc: "Teslimden 30 gün sonra", color: "var(--mavi)" },
          ].map(opt => (
            <button
              key={opt.tur}
              onClick={() => set("odemeTuru", opt.tur)}
              style={{
                padding: "12px",
                borderRadius: "var(--r)",
                border: `2px solid var(--border)`,
                background: form.odemeTuru === opt.tur ? opt.color : "transparent",
                color: form.odemeTuru === opt.tur ? "#fff" : "var(--text2)",
                fontSize: 13,
                fontWeight: 600,
                cursor: "pointer",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: 4,
                transition: "all 0.2s"
              }}
            >
              <div style={{ fontSize: 20 }}>{opt.color === "var(--yesil)" ? "💰" : opt.color === "var(--kirmizi)" ? "⚡" : opt.color === "var(--sari)" ? "⏰" : "📅"}</div>
              <div style={{ color: form.odemeTuru === opt.tur ? "#fff" : opt.color }}>{opt.label}</div>
              <div style={{ fontSize: 9, color: "var(--text3)" }}>{opt.desc}</div>
            </button>
          ))}
        </div>
      </div>

      <button onClick={gonder} className="btn btn-primary btn-full" style={{ padding: "16px" }}>
        📢 İLANI YAYINLA
      </button>
    </div>
  );
}

export function TekliflerSayfasi() {
  const { oturum, konusmaOluştur, ilkMesajiGonder, seferler } = useApp();
  const [kabulEdilen, setKabulEdilen] = useState(new Set());
  const [seciliSefer, setSeciliSefer] = useState(null);
  const [konusmaIdMap, setKonusmaIdMap] = useState({}); // Sefer ID -> Konuşma ID map

  // Gelen teklifler
  const mevcutSeferler = seferler.filter(s => s.durum === "bekliyor");
  const kabulEdilecekler = mevcutSeferler.filter(s => kabulEdilen.has(s.id));

  // Aktif işler
  const aktifSeferler = seferler.filter(s => s.durum === "yolda" || s.durum === "teslima_bekleniyor");

  const kabulEt = (sefer) => {
    setKabulEdilen(prev => new Set([...prev, sefer.id]));
    // Konuşma oluştur ve ID'yi kaydet
    const newConversation = konusmaOluştur({
      partnerId: sefer.kamyoncu,
      partnerAd: sefer.kamyoncu,
      partnerRol: "kamyoncu",
      baslik: `${sefer.yuk} - ${sefer.nereden} → ${sefer.nereye}`,
      resim: "https://api.dicebear.com/7.x/initials/svg?seed=" + sefer.kamyoncu.substring(0, 2).toUpperCase()
    });

    // Map'e kaydet
    setKonusmaIdMap(prev => ({ ...prev, [sefer.id]: newConversation }));

    // İlk mesajı gönder
    setTimeout(() => {
      ilkMesajiGonder(
        newConversation,
        `✓ Teklifinizi kabul ettim. Şimdi convo üzerinden konuşabiliriz.`
      );
    }, 500);

    return newConversation;
  };

  return (
    <div className="scroll-content">
      {/* Aktif İşler Bölümü */}
      {aktifSeferler.length > 0 && (
        <>
          <div className="section-title">AKTİF İŞLER ({aktifSeferler.length})</div>
          {aktifSeferler.map(s => (
            <div key={s.id} className="card" style={{ marginBottom: 10, display: "flex", flexDirection: "column", gap: 12 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                <div className="display" style={{ fontSize: 16 }}>{s.yuk}</div>
                <span className="pill pill-green" style={{ textTransform: "capitalize" }}>Yolda</span>
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ fontWeight: 600 }}>{s.nereden}</span>
                <span style={{ color: "var(--turuncu)" }}>—→</span>
                <span style={{ fontWeight: 600 }}>{s.nereye}</span>
              </div>
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 6 }}>
                <div style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "8px 10px", textAlign: "center" }}>
                  <div style={{ fontSize: 12, color: "var(--text3)" }}>Plaka</div>
                  <div style={{ fontSize: 14, fontWeight: 600 }}>{s.plaka}</div>
                </div>
                <div style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "8px 10px", textAlign: "center" }}>
                  <div style={{ fontSize: 12, color: "var(--text3)" }}>Ücret</div>
                  <div style={{ fontSize: 14, fontWeight: 600 }}>₺{s.ucret.toLocaleString()}</div>
                </div>
                <div style={{ background: "var(--bg2)", borderRadius: "var(--r)", padding: "8px 10px", textAlign: "center" }}>
                  <div style={{ fontSize: 12, color: "var(--text3)" }}>Tonaj</div>
                  <div style={{ fontSize: 14, fontWeight: 600 }}>{s.ton > 0 ? `${s.ton} Ton` : "Serbest"}</div>
                </div>
              </div>
              <button
                onClick={() => {
                  const newConversationId = konusmaOluştur({
                    partnerId: s.kamyoncu,
                    partnerAd: s.kamyoncu,
                    partnerRol: "kamyoncu",
                    baslik: `${s.yuk} - ${s.nereden} → ${s.nereye}`,
                    resim: "https://api.dicebear.com/7.x/initials/svg?seed=" + s.kamyoncu.substring(0, 2).toUpperCase(),
                    bg: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
                  });
                  setKonusmaIdMap(prev => ({ ...prev, [s.id]: newConversationId }));
                }}
                className="btn btn-primary"
                style={{ padding: "10px", fontSize: 13 }}
              >
                💬 Mesajlaş
              </button>
            </div>
          ))}
        </>
      )}

      {/* Gelen Teklifler Bölümü */}
      {kabulEdilecekler.length > 0 && (
        <>
          {aktifSeferler.length > 0 && <div style={{ height: 20 }}></div>}
          <div className="section-title">GELEN TEKLİFLER ({kabulEdilecekler.length})</div>
          {kabulEdilecekler.map(s => (
            <div key={s.id} className="card" style={{ marginBottom: 10, display: "flex", alignItems: "center", gap: 12, border: "1px solid var(--mavi)" }}>
              <div style={{ width: 42, height: 42, borderRadius: "50%", background: "var(--mavi)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, color: "#fff", flexShrink: 0 }}>✓</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 600, fontSize: 14 }}>{s.kamyoncu}</div>
                <div style={{ fontSize: 12, color: "var(--text3)" }}>₺{s.ucret.toLocaleString()} • {s.tarih}</div>
              </div>
              <button
                onClick={() => {
                  const newConversationId = konusmaOluştur({
                    partnerId: s.kamyoncu,
                    partnerAd: s.kamyoncu,
                    partnerRol: "kamyoncu",
                    baslik: `${s.yuk} - ${s.nereden} → ${s.nereye}`,
                    resim: "https://api.dicebear.com/7.x/initials/svg?seed=" + s.kamyoncu.substring(0, 2).toUpperCase(),
                    bg: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
                  });
                  setKonusmaIdMap(prev => ({ ...prev, [s.id]: newConversationId }));
                }}
                className="btn btn-primary"
                style={{ padding: "8px 16px", fontSize: 12 }}
              >
                Konuş
              </button>
            </div>
          ))}
        </>
      )}

      {mevcutSeferler.length === 0 && (
        <div style={{ textAlign: "center", padding: "60px 0", color: "var(--text3)" }}>
          <div style={{ fontSize: 52, marginBottom: 16 }}>📋</div>
          <div style={{ fontSize: 18, marginBottom: 8 }}>Henüz teklif veya aktif iş yok</div>
          <div style={{ fontSize: 14 }}>İlanlar sekmesinden yük vererek başlayın!</div>
        </div>
      )}
    </div>
  );
}

export function MesajlarSayfasi({ onGeri }) {
  const { konusmalar, oturum } = useApp();
  const [secili, setSecili] = useState(null);
  console.log("MesajlarSayfasi - konusmalar:", konusmalar.length, "oturum:", oturum);

  if (secili) {
    return <ChatSayfasi konusmaId={secili} onGeri={() => setSecili(null)} />;
  }

  return (
    <div className="scroll-content">
      <div className="section-title">MESAJLAR ({konusmalar.length})</div>
      {konusmalar.length === 0 ? (
        <div style={{ textAlign: "center", padding: "40px 0", color: "var(--text3)" }}>
          <div style={{ fontSize: 40, marginBottom: 12 }}>💬</div>
          <div>Henüz mesaj yok</div>
        </div>
      ) : (
        konusmalar.map(k => (
          <div key={k.id} className="card" style={{ marginBottom: 8, display: "flex", alignItems: "center", gap: 12, cursor: "pointer" }} onClick={() => setSecili(k.id)}>
            <div style={{ width: 42, height: 42, borderRadius: "50%", background: "var(--bg3)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18, flexShrink: 0 }}>
              {k.partnerRol === "kamyoncu" ? "🚛" : "🏢"}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontWeight: 600, fontSize: 14 }}>{k.partnerAd}</div>
              <div style={{ fontSize: 12, color: "var(--text3)", marginTop: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                {k.mesajlar.length > 0 ? (k.mesajlar[k.mesajlar.length - 1].metin || "📄 Dosya gönderildi") : (k.baslik || "")}
              </div>
            </div>
            <div style={{ flexShrink: 0, textAlign: "right" }}>
              <div style={{ fontSize: 11, color: "var(--text3)" }}>
                {new Date(k.sonOkuma).toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" })}
              </div>
            </div>
          </div>
        ))
      )}
    </div>
  );
}

